-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Die Gruppen-Zielverfolgung bleibt beim Kampfbeginn sichtbar und zeigt weiterhin verfügbare Fortschrittsmeldungen an.","Verschieben, Größenänderung und Bearbeitung werden im Kampf beendet. Andere QT-Fenster schließen sich weiterhin automatisch."},["title"]="Gruppen-Zielverfolgung"}},["version"]="10.2.1",["welcome"]="Behalte den Fortschritt deiner Gruppe auch im Kampf im Blick."},["esES"]={["sections"]={{["items"]={"El seguimiento de objetivos del grupo permanece visible al entrar en combate y sigue mostrando las actualizaciones de progreso disponibles.","Al entrar en combate se detienen el arrastre, el cambio de tamaño y la edición. Las demás ventanas de QT siguen cerrándose automáticamente."},["title"]="Seguimiento de objetivos del grupo"}},["version"]="10.2.1",["welcome"]="Sigue viendo el progreso de tu grupo durante el combate."},["esMX"]={["sections"]={{["items"]={"El seguimiento de objetivos del grupo ahora permanece visible al comenzar un combate y sigue mostrando las actualizaciones de progreso disponibles.","Durante el combate se detienen las acciones de arrastrar, cambiar el tamaño y editar el panel. Las otras ventanas de QT se siguen cerrando automáticamente."},["title"]="Seguimiento de objetivos del grupo"}},["version"]="10.2.1",["welcome"]="Mantén a la vista el progreso de tu grupo durante el combate."},["frFR"]={["sections"]={{["items"]={"Le suivi des objectifs du groupe reste désormais visible au début du combat et continue d’afficher les mises à jour de progression disponibles.","Le déplacement, le redimensionnement et les commandes de modification s’arrêtent en combat. Les autres fenêtres QT se ferment toujours automatiquement."},["title"]="Suivi des objectifs du groupe"}},["version"]="10.2.1",["welcome"]="Gardez un œil sur la progression du groupe pendant les combats."},["itIT"]={["sections"]={{["items"]={"Il tracciamento degli obiettivi del gruppo ora rimane visibile quando inizia il combattimento e continua a mostrare gli aggiornamenti disponibili sui progressi.","Trascinamento, ridimensionamento e modifica vengono interrotti in combattimento. Le altre finestre di QT continuano a chiudersi automaticamente."},["title"]="Tracciamento degli obiettivi del gruppo"}},["version"]="10.2.1",["welcome"]="Tieni d’occhio i progressi del gruppo anche in combattimento."},["koKR"]={["sections"]={{["items"]={"전투가 시작되어도 파티 목표 추적기가 계속 표시되며, 확인 가능한 진행 상황 업데이트도 보여 줍니다.","전투가 시작되면 패널 드래그, 크기 조절 및 편집이 중단됩니다. 다른 QT 창은 기존처럼 자동으로 닫힙니다."},["title"]="파티 목표 추적기"}},["version"]="10.2.1",["welcome"]="전투 중에도 파티의 진행 상황을 확인하세요."},["ptBR"]={["sections"]={{["items"]={"O rastreador de objetivos do grupo agora permanece visível quando o combate começa e continua mostrando as atualizações de progresso disponíveis.","Arrastar, redimensionar e editar o painel são ações interrompidas durante o combate. As outras janelas do QT continuam fechando automaticamente."},["title"]="Rastreador de objetivos do grupo"}},["version"]="10.2.1",["welcome"]="Acompanhe o progresso do grupo mesmo durante o combate."},["ruRU"]={["sections"]={{["items"]={"Панель целей группы теперь остаётся видимой при начале боя и продолжает показывать доступные обновления прогресса.","В бою прекращаются перетаскивание, изменение размера и редактирование панели. Остальные окна QT по-прежнему закрываются автоматически."},["title"]="Отслеживание целей группы"}},["version"]="10.2.1",["welcome"]="Следите за прогрессом группы, не отвлекаясь от боя."},["zhCN"]={["sections"]={{["items"]={"进入战斗后，队伍目标追踪器现在会保持显示，并继续呈现可用的进度更新。","战斗开始时会停止面板拖动、缩放和编辑。其他 QT 窗口仍会自动关闭。"},["title"]="队伍目标追踪器"}},["version"]="10.2.1",["welcome"]="战斗中也能随时查看队伍进度。"},["zhTW"]={["sections"]={{["items"]={"進入戰鬥後，隊伍目標追蹤器現在會保持顯示，並持續呈現可取得的進度更新。","戰鬥開始時會停止面板拖曳、調整大小與編輯。其他 QT 視窗仍會自動關閉。"},["title"]="隊伍目標追蹤器"}},["version"]="10.2.1",["welcome"]="戰鬥中也能掌握隊伍進度。"}}
